msg.payload = msg.payload['mode']['raw'];

if (msg.payload === '1' || msg.payload === '7') {
    msg.payload = '0';
}

return msg;

// Energy charts of the air conditioners, from the day power of each unit
// (get_day_power_ex: 24 values per day, in 0.1 kWh, for today and yesterday, heating and cooling)
const FIELDS = [
    { 'key': 'heat', 'name': 'Chaud', 'slot': 2 },
    { 'key': 'cool', 'name': 'Froid', 'slot': 1 }
];
const DAYS = ['dim.', 'lun.', 'mar.', 'mer.', 'jeu.', 'ven.', 'sam.'];
const DAYS_LONG = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];
const MONTHS_LONG = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];

function pad(n) {
    return String(n).padStart(2, '0');
}

// a tab change to another page: nothing to do
if (typeof msg.tab === 'string' && msg.tab !== 'chart') {
    return null;
}

const units = global.get('units', 'default') || {};
const controls = global.get('controls', 'memoryOnly') || {};

if (msg.topic === 'select') {
    flow.set('current_chart', String(msg.payload || ''), 'memoryOnly');
}

// units list, the selected one is kept for all browsers
const meters = Object.keys(units).map(host => ({
    'value': host,
    'label': (units[host].name || host) + (units[host].location ? ' - ' + units[host].location : '')
}));
let host = flow.get('current_chart', 'memoryOnly') || '';
if (typeof units[host] !== 'object') {
    host = meters.length > 0 ? meters[0].value : '';
    flow.set('current_chart', host, 'memoryOnly');
}

if (host === '') {
    return { 'payload': { 'error': 'Aucun climatiseur, ajoutez-en un depuis la page Ajouter.', 'meters': [], 'periods': [], 'fields': [] } };
}

// hourly series in Wh, null when the unit did not send it
const control = controls[host] || {};
const series = k => control[k] && Array.isArray(control[k].value)
    ? control[k].value.map(v => Math.max(0, Number(v) || 0) * 100)
    : null;
const today = { 'heat': series('curr_day_heat'), 'cool': series('curr_day_cool') };
const yesterday = { 'heat': series('prev_1day_heat'), 'cool': series('prev_1day_cool') };
const fields = FIELDS.filter(f => today[f.key] || yesterday[f.key]);

if (fields.length === 0) {
    return { 'payload': { 'error': 'Pas encore de consommation reçue de ce climatiseur, elle est relevée toutes les 2 minutes.', 'meters': meters, 'selected': host, 'periods': [], 'fields': [] } };
}

const now = new Date();
const midnight = new Date(now.getFullYear(), now.getMonth(), now.getDate());

function bar(key, label, title, values) {
    let total = 0;
    for (const k in values) {
        total += values[k];
    }

    return { 'key': key, 'label': label, 'title': title, 'values': values, 'total': total };
}

// last 24 hours: yesterday after the current hour, then today up to the current hour
let hours = [];
for (let i = 23; i >= 0; i--) {
    const d = new Date(now.getTime() - i * 3600000);
    const h = d.getHours();
    const day = d >= midnight ? today : yesterday;
    let values = {};
    for (const f of fields) {
        if (day[f.key] && day[f.key][h] !== undefined) {
            values[f.key] = day[f.key][h];
        }
    }
    hours.push(bar('h' + i, h + 'h', pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + ' de ' + h + 'h à ' + ((h + 1) % 24) + 'h', values));
}

// yesterday and today
let days = [];
[[yesterday, 1], [today, 0]].forEach(([day, back]) => {
    const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() - back);
    let values = {};
    for (const f of fields) {
        if (day[f.key]) {
            values[f.key] = day[f.key].reduce((a, v) => a + v, 0);
        }
    }
    days.push(bar('d' + back, DAYS[d.getDay()] + ' ' + d.getDate(), DAYS_LONG[d.getDay()] + ' ' + d.getDate() + ' ' + MONTHS_LONG[d.getMonth()], values));
});

const periods = [
    { 'key': 'hour', 'title': 'Par heure, 24 dernières heures', 'bars': hours },
    { 'key': 'day', 'title': 'Par jour, hier et aujourd\'hui', 'bars': days }
].map(p => Object.assign(p, { 'total': p.bars.reduce((a, b) => a + b.total, 0) }));

node.status({ fill: 'green', shape: 'dot', text: host + ' ' + now.toLocaleTimeString('fr-FR') });

return {
    'payload': {
        'error': '',
        'meters': meters,
        'selected': host,
        'fields': fields,
        'periods': periods,
        'updated': now.toLocaleString('fr-FR')
    }
};

let units = global.get('units', 'default') || {};
let size = Object.keys(units).length;
if (size < 2) {
    msg.class = '';
    msg.enabled = true;
    msg.payload = {
        'model': 'BRP069Bxx',
        'name': 'Clim_' + size,
        'location': 'Maison',
        'host': '192.168.0.101'
    }
} else {
    msg.class = 'remove';
    msg.enabled = false;
    msg.payload = {};
}

return msg;

let units = global.get('units', 'default') || {};
if (typeof units[msg.payload.host] === 'object') {
    msg.payload = 'Cet élément est déjà configuré'
    node.send([null, msg]);
} else if (msg.payload.name !== ' ' && msg.payload.location !== ' ' && msg.payload.host !== ' ' && msg.payload.port !== ' ') {
    units[msg.payload.host] = msg.payload;
    global.set('units', units, 'default');
    node.send([msg, null]);
}

return;

let control = global.get('controls["' + msg.topic +'"]', 'memoryOnly');

const describe = global.get('describe', 'memoryOnly');
const topic = global.get('mqtt.topic', 'default') || '';
const source = 'daikin';
const sn = control.id?.value || '';

if (topic === '' || sn === '') {

    return;
}

for (const k in control) {
    if (typeof describe.control[k] === 'object' && flow.get('last["' + sn + '_' + k + '"]', 'memoryOnly') !== control[k]['raw']) {
        flow.set('last["' + sn + '_' + k + '"]', control[k]['raw'], 'memoryOnly');
        let newMsg = {
            'topic': [topic, 'get', source, sn, describe.control[k][1]].join('/'),
            'payload': describe.control[k][3] === 'enum' ? String(control[k]['raw']) : (describe.control[k][3] === 'binary' ? Number(control[k]['raw']) : control[k]['raw'])
        };

        node.send([newMsg]);
    }
}
return;

const enabled = global.get('mqtt.enabled', 'default') || false;
const topic = global.get('mqtt.topic', 'default') || '';
const controls = global.get('controls', 'memoryOnly') || {};
const describe = global.get('describe', 'memoryOnly') || {};
const source = 'daikin';

// Options labels in the language of the MQTT configuration
const lang = global.get('mqtt.lang', 'default') || 'fr';
const words = (describe.translate || {})[lang] || {};
const tr = s => typeof s === 'string' && typeof words[s] === 'string' ? words[s] : s;
const trOptions = o => { let r = {}; for (const k in (o || {})) { r[k] = tr(o[k]); } return r; };
// Home Assistant template mapping a value with a dictionary
const haMap = m => '{{ ' + JSON.stringify(m) + '[value] | default(value) }}';


if (!enabled && topic === '') {

    return;
}

// Source definition
let srcMsg = {
    'topic': [topic, 'discovery', source].join('/'),
    'payload': describe.app,
    'qos': 0,
    'retain': true
};

node.send([srcMsg]);

// dknr
for (const host in controls) {
    if (typeof controls[host]['id'] !== 'object') {

        continue;
    }
    let id = controls[host]['id']['raw'];

    for (const entity in describe.control) {
        let dknrMsg = {
            'topic': [topic, 'discovery', source, id, describe.control[entity][1]].join('/'),
            'payload': {
                'name': describe.control[entity][0],
                'group': describe.control[entity][2],
                'type': describe.control[entity][3],
                'unit': describe.control[entity][4],
                'value': describe.control[entity][5],
                'options': describe.control[entity][3] === 'binary' ? {} : trOptions(describe.control[entity][6])
            },
            'qos': 0,
            'retain': true
        };

        node.send(dknrMsg);
    }
}

// ha
const discovery = global.get('mqtt.homeassistant', 'default') || '';
msg.qos = 0;
msg.retain = true

for (const host in controls) {
    if (typeof controls[host]['id'] !== 'object') {

        continue;
    }
    let id = controls[host]['id']['raw'];

    for (const entity in describe.control) {
        let key = describe.control[entity][1];
        msg.topic = discovery + '/' + describe.control[entity][7] + '/daikin/' + id + '_' + key + '/config';

        if (describe.control[entity][7] === 'sensor') {
            msg.payload = {
                'unique_id': ['dknr', source, id, key].join('_'),
                'name': describe.control[entity][0],
                'state_topic': [topic, 'get', source, id, key].join('/'),
                'state_class': describe.control[entity][8],
                'device_class': describe.control[entity][9],
                'unit_of_measurement': describe.control[entity][4],
                'device': {
                    'identifiers': [
                        id
                    ],
                    'manufacturer': 'Daikin',
                    'model': 'daikin_' + id,
