for (const c in describe.control) {
    if (describe.control[c][1] === entity) {
        key = c;
    }
}
if (key === '' || describe.control[key][2] !== 'command') {

    return;
}

for (const host in controls) {
    if (id === controls[host]['id']['raw']) {

        // pilot by full name in any language (from ha)
        if (typeof describe.control[key][6] === 'object') {
            const words = describe.translate || {};
            for (const src in describe.control[key][6]) {
                const names = [describe.control[key][6][src]].concat(Object.keys(words).map(l => words[l][describe.control[key][6][src]]));
                if (names.includes(value)) {
                    value = src;
                }
            }
        }

        // binary: 1 / 0 (ON / OFF accepted)
        if (describe.control[key][3] === 'binary') {
            const v = value.toUpperCase();
            if (['1', 'ON', 'TRUE'].includes(v)) {
                value = '1';
            } else if (['0', 'OFF', 'FALSE'].includes(v)) {
                value = '0';
            } else {
                node.status({ fill: 'red', text: id + ' - ' + entity + ' - ' + value + ' ?' });

                return;
            }
        }

        let raw = value;
        let full = value;
        let unit = describe.control[key][4];
        let label = describe.control[key][0];


        // Convert numeric value to number
        if (!isNaN(value) && isFinite(Number(value))) {
            value = Number(value);
        }

        // enum and binary labels
        if (['enum', 'binary'].includes(describe.control[key][3])) {
            full = describe.control[key][6][raw];
        }

        controls[host][key] = {
            'unit': unit,
            'label': label,
            'raw': raw,
            'value': value,
            'full': full
        };

        global.set('controls', controls, 'memoryOnly');

        msg.topic = host;
        msg.payload = controls;

        return msg;
